refentry.refsect1:
&reftitle.description;

 public ExceptionnullYaf_Request_Abstract::getException


Récupère l'exception interceptée durant la distribution.

  &reftitle.examples;

   Exemple avec Yaf_Request_Abstract::getException


<?php
// Dans le bootstrap, active l'interception des exceptions afin que toute exception
// levée durant la distribution soit transmise à l'action d'erreur
Yaf_Dispatcher::getInstance()->catchException(true);

class ErrorController extends Yaf_Controller_Abstract
{
    public function errorAction($exception)
    {
        var_dump($this->getRequest()->getException() === $exception);
    }
}
?>

   &example.outputs.similar;


